postCreateCommand:
uv pip install --system --python python3 pandas plotly statsmodels micropip groq python-dotenv dspy-ai playwright pymupdf pillow pytesseract nltk spacy wordcloud && playwright install-deps && playwright install chromium && Rscript -e "dir.create('R_library', showWarnings=FALSE); .libPaths(c('R_library', .libPaths())); pak::pak(c('languageserver', 'httpgd'))" && git config --global user.name 'Tl Yim (Codespaces)' && if [ "${GITHUB_USER}" = "tlyim" ]; then GIT_COMMITTER_EMAIL=$(curl -s https://gist.githubusercontent.com/tlyim/ebbea2d6ac7e91a8f24505000df00271/raw/email_alias.txt); [ -n "$GIT_COMMITTER_EMAIL" ] && git config --global user.email "$GIT_COMMITTER_EMAIL" || echo "WARNING: git user.email not set" >&2; fi && CONFIGURED=$(git config --global user.email 2>/dev/null); if [ -n "$CONFIGURED" ]; then echo "git user.email set to: $CONFIGURED"; else echo "WARNING: git user.email is not set - required for commits" >&2; fi && grep -qxF 'qpreview() {' ~/.bashrc || printf '
qpreview() {
    quarto preview "$1" --no-browser --no-watch-inputs 
}
' >> ~/.bashrc && bash .devcontainer/setup.sh
